32	export class AboutSceneRig {
33	  compose(state: AboutSceneState): SceneFromState {
34	    return {
35	      camera: {
36	        position: { ...state.camera.position },
37	        fov: state.camera.fov,
38	      },
39	      cameraTarget: {
40	        position: { ...state.camera.target },
41	      },
42	      [aboutBackgroundId]: state.background,
43	      [earthId]: state.earth,
44	      [rocketId]: state.rocket,
45	      [jetEngineId]: {
46	        position: { ...state.jetEngine.position },
47	        rotation: { ...state.jetEngine.rotation },
48	        scale: { ...state.jetEngine.scale },
49	        visible: state.jetEngine.visible,
50	      },
51	      [astronautId]: state.astronaut,
52	      [terrianId]: state.terrian,
53	      [gravityBallsId]: state.gravityBalls,
54	    } as unknown as SceneFromState;
55	  }
56	
57	  apply(engine: Engine, state: AboutSceneState): void {
58	    engine.setState(this.compose(state));
59	    const camera = engine.getCamera();
60	    camera.lookAt(engine.getCameraTarget().position);
61	    this._applyLight(engine, state.light);
62	    this._applyRocket(engine, state.rocket);
63	    this._applyJetEngine(engine, state.jetEngine);
64	  }
65	
66	  read(engine: Engine): AboutSceneState {
67	    const camera = engine.getCamera();
68	    const target = engine.getCameraTarget();
69	    return {
70	      camera: {
71	        position: {
72	          x: this._toFinite(camera.position.x, 0),
73	          y: this._toFinite(camera.position.y, 0),
74	          z: this._toFinite(camera.position.z, 18),
75	        },
76	        target: {
77	          x: this._toFinite(target.position.x, 0),
78	          y: this._toFinite(target.position.y, 0),
79	          z: this._toFinite(target.position.z, 0),
80	        },
81	        fov: this._toFinite(camera.fov, 64),
82	      },
83	      light: this._readLight(engine),
84	      background: this._readBackground(engine),
85	      earth: this._readTransform(engine, earthId),
86	      rocket: this._readRocket(engine),
87	      jetEngine: this._readJetEngine(engine),
88	      astronaut: this._readTransform(engine, astronautId),
89	      terrian: this._readTransform(engine, terrianId),
90	      gravityBalls: this._readTransform(engine, gravityBallsId),
91	    };
92	  }
93	
94	  private _readRocket(engine: Engine): MainRocketState {
95	    const transform = this._readTransform(engine, rocketId);
96	    const defaults = DEFAULT_MAIN_SCENE_STATE.rocket;
97	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
98	    return {
99	      ...transform,
100	      flame: rocket?.getFlameState() ?? defaults.flame,
101	    };
102	  }
103	
104	  private _applyRocket(engine: Engine, state: MainRocketState): void {
105	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
106	    if (!rocket) return;
107	    rocket.setFlameState(state.flame);
108	  }
109	
110	  private _applyJetEngine(engine: Engine, state: MainJetEngineState): void {
111	    const jet = engine.getSceneObjectById(jetEngineId) as SceneObject<
112	      JetEngineTweenProps
113	    > | null;
114	    if (!jet || typeof jet.setTimelineVars !== "function") return;
