758	  private _sheetHasMeaningfulKeyframes(
759	    sheetState: Record<string, unknown>,
760	    sheetId: AboutTheatreSheetId,
761	  ): boolean {
762	    const sequenceState = this._readRecord(sheetState.sequence);
763	    if (!sequenceState) return false;
764	    const tracksByObject = this._readRecord(sequenceState.tracksByObject);
765	    if (!tracksByObject) return false;
766	    const objectTracks = this._readRecord(tracksByObject[ABOUT_THEATRE_OBJECT_ID]);
767	    if (!objectTracks) return false;
768	    const trackData = this._readRecord(objectTracks.trackData);
769	    if (!trackData) return false;
