62	        sheetId: AboutTheatreSheetId,
63	        length: number,
64	      ) => AboutTheatrePlaybackRange;
65	      rate: number;
66	      fallbackSync: (engine: Engine) => void;
67	      completeSync: (engine: Engine, position: number) => void;
68	    },
69	  ): Promise<void> {
70	    if (this._autoplayTask) return this._autoplayTask;
71	    this._autoplayTask = this._runSheetAutoplay(engine, options).finally(() => {
72	      this._autoplayDispose?.();
