82	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
83	    renderer.setClearAlpha(0);
84	    this._renderer = renderer;
85	
86	    const scene = new THREE.Scene();
87	    this._scene = scene;
88	
89	    const w = Math.max(canvas.clientWidth, 1);
90	    const h = Math.max(canvas.clientHeight, 1);
91	    // Frontal elevated view: ring curves left/right into depth
92	    const camera = new THREE.PerspectiveCamera(65, w / h, 0.1, 1000);
93	    camera.position.set(0, 3, 22);
