100	    this._group = group;
101	    scene.add(group);
102	
103	    let imageUrls: string[] = [];
104	    try {
105	      const response = await fetchWorksList(0, MAX_IMAGES, null);
106	      imageUrls = response.items
107	        .filter((item: WorkApiItem) => item.thumbnailImage.length > 0)
108	        .map((item: WorkApiItem) => item.thumbnailImage)
109	        .slice(0, MAX_IMAGES);
110	    } catch {
111	      // fallback to colored cards
112	    }
113	
114	    if (this._disposed) return;
115	
116	    if (imageUrls.length > 0) {
