122	      const radius = computeRadius(textures.length);
123	      textures.forEach((texture, i) => {
124	        if (texture) this._textures.push(texture);
125	        this._addCard(group, i, textures.length, texture, radius);
126	      });
127	    } else {
128	      const radius = computeRadius(FALLBACK_COUNT);
129	      for (let i = 0; i < FALLBACK_COUNT; i++) {
130	        this._addCard(group, i, FALLBACK_COUNT, null, radius);
131	      }
132	    }
