139	  dispose(): void {
140	    this._disposed = true;
141	    this._stopRaf();
142	
143	    this._resizeObserver?.disconnect();
144	    this._resizeObserver = null;
145	
146	    this._intersectionObserver?.disconnect();
147	    this._intersectionObserver = null;
148	
149	    this._geometries.forEach((g) => g.dispose());
150	    this._geometries = [];
151	
152	    this._materials.forEach((m) => m.dispose());
153	    this._materials = [];
154	
155	    this._textures.forEach((t) => t.dispose());
156	    this._textures = [];
157	
158	    this._renderer?.dispose();
159	    this._renderer?.forceContextLoss();
160	    this._renderer = null;
161	    this._scene = null;
162	    this._camera = null;
163	    this._group = null;
164	    this._canvas = null;
165	  }
166	
167	  private _addCard(
168	    group: THREE.Group,
169	    index: number,
170	    total: number,
171	    texture: THREE.Texture | null,
172	    radius: number,
173	  ): void {
174	    const angle = (index / total) * Math.PI * 2;
175	    const x = radius * Math.cos(angle);
176	    const z = radius * Math.sin(angle);
177	
178	    const geo = new THREE.PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
179	    this._geometries.push(geo);
180	
181	    const mat = createCardMaterial(
182	      texture,
183	      FALLBACK_COLORS[index % FALLBACK_COLORS.length],
