184	  private _intersectionObserver: IntersectionObserver | null = null;
185	
186	  private _scrollVelocity = 0;
187	  private _lastInteractionMs = 0;
188	  private _isAutoPlaying = false;
189	  private _autoPlayIntervalId: ReturnType<typeof setInterval> | null = null;
190	  private _hoveredIndex = -1;
191	  private _touchLastY = 0;
192	
193	  private readonly _pointerNDC = new THREE.Vector2();
